import re
from typing import Any


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_norm(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", od_text(value).lower()).strip()


def as_number(value: Any) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", str(value)) or 0)
    except ValueError:
        return 0.0


account_code = od_text(params.get("account_code"))
action = od_text(params.get("action")).lower()
rule = re.sub(r"\s+", " ", od_text(params.get("rule")))[:500]
number = int(as_number(params.get("rule_number")))
changed = False
result = ""
customer_name = ""
rules_now: list[str] = []
profile_id = ""
if action not in ("add", "change", "remove"):
    result = "Nothing was changed: the action must be add, change or remove."
elif not account_code:
    result = "Nothing was changed: give the customer's account code."
else:
    page = api.records.list(type_slug="od_customer_profiles", limit=200, q=account_code)
    hits = [r for r in (page.get("records") or []) if od_text(od_data(r).get("account_code")).upper() == account_code.upper()]
    if not hits:
        result = "Nothing was changed: no customer order profile has the account code " + account_code + "."
    else:
        profile_id = od_text(hits[0].get("id"))
        customer_name = od_text(hits[0].get("title")) or od_text(od_data(hits[0]).get("name"))
        rules_now = [line.strip() for line in od_text(od_data(hits[0]).get("order_rules")).splitlines() if line.strip()]
        new_rules = list(rules_now)
        if action == "add":
            if not rule:
                result = "Nothing was changed: give the rule to add."
            elif any(od_norm(r) == od_norm(rule) for r in new_rules):
                result = customer_name + " already has this rule. Nothing was changed."
            elif len(new_rules) >= 40:
                result = "Nothing was changed: " + customer_name + " already has 40 rules. Remove or merge one first."
            else:
                new_rules.append(rule)
                result = "Rule " + str(len(new_rules)) + " added for " + customer_name + ": " + rule
        elif number < 1 or number > len(new_rules):
            result = "Nothing was changed: " + customer_name + " has " + str(len(new_rules)) + " rules. Give the number of the one to " + action + "."
        elif action == "change":
            old = new_rules[number - 1]
            if not rule:
                result = "Nothing was changed: give the new wording of the rule."
            elif od_norm(old) == od_norm(rule):
                result = "Rule " + str(number) + " for " + customer_name + " already reads this way. Nothing was changed."
            else:
                new_rules[number - 1] = rule
                result = "Rule " + str(number) + " for " + customer_name + " changed from: " + old + " To: " + rule
        else:
            old = new_rules.pop(number - 1)
            result = "Rule " + str(number) + " removed for " + customer_name + ": " + old
        if new_rules != rules_now:
            new_text = "\n".join(new_rules)
            if len(new_text) > 5000:
                result = "Nothing was changed: the rules of " + customer_name + " would be longer than the profile allows. Shorten or remove one first."
            else:
                api.records.update(type_slug="od_customer_profiles", record_id=profile_id, record={"data": {"order_rules": new_text}})
                rules_now = new_rules
                changed = True
